#!/usr/bin/env python3
"""IPL 2026 Ball-by-Ball Analytics Report Generator"""

import pandas as pd
import json
import math
from collections import defaultdict

# ── Load data ──────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

# Clean up: treat empty strings as NaN for dismissal columns
for col in ['wicket_type', 'player_dismissed', 'fielder']:
    df[col] = df[col].replace('', pd.NA)

# ── Derived columns ────────────────────────────────────────────────────────────
df['total_runs'] = df['runs_of_bat'] + df['extras']
df['is_boundary_4'] = (df['runs_of_bat'] == 4).astype(int)
df['is_boundary_6'] = (df['runs_of_bat'] == 6).astype(int)
df['is_boundary'] = ((df['runs_of_bat'] == 4) | (df['runs_of_bat'] == 6)).astype(int)
df['is_dot'] = ((df['runs_of_bat'] == 0) & (df['extras'] == 0)).astype(int)
df['is_wicket'] = df['wicket_type'].notna().astype(int)
df['over_int'] = df['over'].apply(lambda x: int(str(x).split('.')[0]))

# Phase classification
def phase(over_int):
    if over_int <= 5:
        return 'Powerplay (0-5)'
    elif over_int <= 14:
        return 'Middle (6-14)'
    else:
        return 'Death (15-19)'

df['phase'] = df['over_int'].apply(phase)

# ── Tournament-level KPIs ──────────────────────────────────────────────────────
total_deliveries = len(df)
total_runs_scored = df['total_runs'].sum()
total_bat_runs = df['runs_of_bat'].sum()
total_extras = df['extras'].sum()
total_wickets = df['is_wicket'].sum()
total_boundaries = df['is_boundary'].sum()
total_dots = df['is_dot'].sum()

# Count valid (non-wide) deliveries for dot/boundary %
valid_deliveries = df[df['wide'] == 0]
n_valid = len(valid_deliveries)

# Matches
n_matches = df['match_no'].nunique()
# Each match has 2 innings, each innings ~20 overs
# Total overs = sum of distinct overs per innings per match
# Approximate total overs from distinct over_int values per match-innings
overs_df = df.groupby(['match_no', 'innings', 'over_int']).size().reset_index()
total_overs = len(overs_df)

avg_runs_per_over = total_runs_scored / total_overs if total_overs > 0 else 0
boundary_pct = 100 * total_boundaries / n_valid if n_valid > 0 else 0
dot_ball_pct = 100 * total_dots / n_valid if n_valid > 0 else 0
extras_per_match = total_extras / n_matches if n_matches > 0 else 0
wickets_per_match = total_wickets / n_matches if n_matches > 0 else 0

# Venues
venues = df['venue'].unique().tolist()
n_venues = len(venues)

# Teams
teams = sorted(set(df['batting_team'].unique()) | set(df['bowling_team'].unique()))
n_teams = len(teams)

print("=== KPIs ===")
print(f"Matches: {n_matches}")
print(f"Total deliveries: {total_deliveries}")
print(f"Total runs: {total_runs_scored}")
print(f"Total wickets: {total_wickets}")
print(f"Avg RPO: {avg_runs_per_over:.2f}")
print(f"Boundary %: {boundary_pct:.1f}%")
print(f"Dot ball %: {dot_ball_pct:.1f}%")
print(f"Extras/match: {extras_per_match:.1f}")
print(f"Wickets/match: {wickets_per_match:.1f}")

# ── Batting Analysis ───────────────────────────────────────────────────────────
bat_agg = df.groupby('striker').agg(
    runs=('runs_of_bat', 'sum'),
    balls=('wide', lambda x: (x == 0).sum()),  # non-wide deliveries faced
    fours=('is_boundary_4', 'sum'),
    sixes=('is_boundary_6', 'sum'),
    dismissals=('is_wicket', 'sum'),
).reset_index()
bat_agg['strike_rate'] = (bat_agg['runs'] / bat_agg['balls'] * 100).round(1)
bat_agg = bat_agg[bat_agg['balls'] >= 10]  # min 10 balls faced
bat_agg = bat_agg.sort_values('runs', ascending=False).head(15)

print("\n=== Top Batters ===")
print(bat_agg[['striker','runs','balls','strike_rate','fours','sixes']].head(10).to_string(index=False))

# Phase-wise batting
phase_bat = df.groupby('phase').agg(
    total_runs=('runs_of_bat', 'sum'),
    boundaries=('is_boundary', 'sum'),
    dots=('is_dot', 'sum'),
    wickets=('is_wicket', 'sum'),
    deliveries=('wide', lambda x: (x == 0).sum())
).reset_index()
phase_bat['run_rate'] = (phase_bat['total_runs'] / phase_bat['deliveries'] * 6).round(2)
phase_bat['boundary_pct'] = (phase_bat['boundaries'] / phase_bat['deliveries'] * 100).round(1)
phase_bat['dot_pct'] = (phase_bat['dots'] / phase_bat['deliveries'] * 100).round(1)
# Sort phases
phase_order = ['Powerplay (0-5)', 'Middle (6-14)', 'Death (15-19)']
phase_bat['phase_order'] = phase_bat['phase'].map({p: i for i, p in enumerate(phase_order)})
phase_bat = phase_bat.sort_values('phase_order')

print("\n=== Phase Batting ===")
print(phase_bat.to_string(index=False))

# Over-by-over run rate
over_agg = df.groupby('over_int').agg(
    total_runs=('runs_of_bat', 'sum'),
    deliveries=('wide', lambda x: (x == 0).sum()),
).reset_index()
over_agg['rpo'] = (over_agg['total_runs'] / over_agg['deliveries'] * 6).round(2)

# ── Bowling Analysis ───────────────────────────────────────────────────────────
bowl_agg = df.groupby('bowler').agg(
    wickets=('is_wicket', 'sum'),
    runs_conceded=('total_runs', 'sum'),
    deliveries=('wide', lambda x: (x == 0).sum()),
    dots=('is_dot', 'sum'),
    wides=('wide', 'sum'),
    noballs=('noballs', 'sum'),
).reset_index()
bowl_agg['overs_bowled'] = (bowl_agg['deliveries'] / 6).round(1)
bowl_agg['economy'] = (bowl_agg['runs_conceded'] / bowl_agg['overs_bowled']).round(2)
bowl_agg['dot_pct'] = (bowl_agg['dots'] / bowl_agg['deliveries'] * 100).round(1)
bowl_agg['bowling_avg'] = (bowl_agg['runs_conceded'] / bowl_agg['wickets'].replace(0, float('nan'))).round(1)
bowl_agg = bowl_agg[bowl_agg['deliveries'] >= 12]  # min 2 overs
bowl_agg_wickets = bowl_agg.sort_values('wickets', ascending=False).head(15)
bowl_agg_economy = bowl_agg[bowl_agg['wickets'] >= 1].sort_values('economy').head(10)

print("\n=== Top Bowlers by Wickets ===")
print(bowl_agg_wickets[['bowler','wickets','economy','dot_pct','deliveries']].head(10).to_string(index=False))

# Dismissal types
dismissals = df[df['wicket_type'].notna()].groupby('wicket_type').size().reset_index(name='count')
dismissals = dismissals.sort_values('count', ascending=False)
print("\n=== Dismissal Types ===")
print(dismissals.to_string(index=False))

# ── Team Comparison ────────────────────────────────────────────────────────────
# Batting team stats
team_bat = df.groupby('batting_team').agg(
    runs_scored=('runs_of_bat', 'sum'),
    boundaries=('is_boundary', 'sum'),
    sixes=('is_boundary_6', 'sum'),
    dots_faced=('is_dot', 'sum'),
    balls_faced=('wide', lambda x: (x == 0).sum()),
    wickets_lost=('is_wicket', 'sum'),
    extras_received=('extras', 'sum'),
).reset_index()
team_bat['strike_rate'] = (team_bat['runs_scored'] / team_bat['balls_faced'] * 100).round(1)
team_bat['boundary_pct'] = (team_bat['boundaries'] / team_bat['balls_faced'] * 100).round(1)
team_bat = team_bat.sort_values('runs_scored', ascending=False)

# Bowling team stats
team_bowl = df.groupby('bowling_team').agg(
    runs_conceded=('total_runs', 'sum'),
    wickets_taken=('is_wicket', 'sum'),
    extras_conceded=('extras', 'sum'),
    wides=('wide', 'sum'),
    noballs=('noballs', 'sum'),
    dots_bowled=('is_dot', 'sum'),
    balls_bowled=('wide', lambda x: (x == 0).sum()),
).reset_index()
team_bowl['economy'] = (team_bowl['runs_conceded'] / (team_bowl['balls_bowled'] / 6)).round(2)
team_bowl['dot_pct'] = (team_bowl['dots_bowled'] / team_bowl['balls_bowled'] * 100).round(1)
team_bowl = team_bowl.sort_values('wickets_taken', ascending=False)

print("\n=== Team Batting ===")
print(team_bat.to_string(index=False))

# ── Extras Analysis ────────────────────────────────────────────────────────────
extras_by_team = df.groupby('bowling_team').agg(
    total_extras=('extras', 'sum'),
    wides=('wide', 'sum'),
    noballs=('noballs', 'sum'),
    legbyes=('legbyes', 'sum'),
    byes=('byes', 'sum'),
    balls_bowled=('wide', lambda x: (x == 0).sum()),
).reset_index()
extras_by_team['extras_per_over'] = (extras_by_team['total_extras'] / (extras_by_team['balls_bowled']/6)).round(2)
extras_by_team = extras_by_team.sort_values('total_extras', ascending=False)

# Innings by match for extras per match
extras_per_match_df = df.groupby('match_no')['extras'].sum().reset_index()
extras_per_match_by_match = extras_per_match_df['extras'].mean()

# ── Venue Analysis ────────────────────────────────────────────────────────────
venue_stats = df.groupby('venue').agg(
    matches=('match_no', 'nunique'),
    total_runs=('total_runs', 'sum'),
    wickets=('is_wicket', 'sum'),
    balls=('wide', lambda x: (x == 0).sum()),
).reset_index()
venue_stats['avg_rpo'] = (venue_stats['total_runs'] / (venue_stats['balls']/6)).round(2)
venue_stats['avg_wickets_per_match'] = (venue_stats['wickets'] / (venue_stats['matches'] * 2)).round(1)
venue_stats = venue_stats.sort_values('avg_rpo', ascending=False)

# Short venue names
def short_venue(v):
    return v.split(',')[0].strip()

venue_stats['venue_short'] = venue_stats['venue'].apply(short_venue)

# Innings comparison (1st vs 2nd innings)
innings_stats = df.groupby('innings').agg(
    total_runs=('total_runs', 'sum'),
    wickets=('is_wicket', 'sum'),
    balls=('wide', lambda x: (x == 0).sum()),
    boundaries=('is_boundary', 'sum'),
    dots=('is_dot', 'sum'),
).reset_index()
innings_stats['rpo'] = (innings_stats['total_runs'] / (innings_stats['balls']/6)).round(2)
innings_stats['boundary_pct'] = (innings_stats['boundaries'] / innings_stats['balls'] * 100).round(1)
innings_stats['dot_pct'] = (innings_stats['dots'] / innings_stats['balls'] * 100).round(1)

print("\n=== Innings Stats ===")
print(innings_stats.to_string(index=False))

# ── Build chart data as JSON strings ──────────────────────────────────────────

# Top batters chart data
top_bat_names = bat_agg['striker'].head(10).tolist()
top_bat_runs = bat_agg['runs'].head(10).tolist()
top_bat_sr = bat_agg['strike_rate'].head(10).tolist()
top_bat_fours = bat_agg['fours'].head(10).tolist()
top_bat_sixes = bat_agg['sixes'].head(10).tolist()

# Top bowlers chart data
top_bowl_names = bowl_agg_wickets['bowler'].head(10).tolist()
top_bowl_wkts = bowl_agg_wickets['wickets'].head(10).tolist()
top_bowl_eco = bowl_agg_wickets['economy'].head(10).tolist()
top_bowl_dot = bowl_agg_wickets['dot_pct'].head(10).tolist()

# Over-by-over RPO
over_list = over_agg['over_int'].tolist()
over_rpo = over_agg['rpo'].tolist()

# Phase data
phase_labels = phase_bat['phase'].tolist()
phase_rr = phase_bat['run_rate'].tolist()
phase_boundary_pct = phase_bat['boundary_pct'].tolist()
phase_dot_pct = phase_bat['dot_pct'].tolist()
phase_wickets = phase_bat['wickets'].tolist()

# Dismissal types
dismissal_labels = dismissals['wicket_type'].tolist()
dismissal_counts = dismissals['count'].tolist()

# Team batting
tb_teams = team_bat['batting_team'].tolist()
tb_runs = team_bat['runs_scored'].tolist()
tb_sr = team_bat['strike_rate'].tolist()
tb_boundary = team_bat['boundary_pct'].tolist()

# Team bowling
tbw_teams = team_bowl['bowling_team'].tolist()
tbw_wkts = team_bowl['wickets_taken'].tolist()
tbw_eco = team_bowl['economy'].tolist()
tbw_dot = team_bowl['dot_pct'].tolist()

# Extras by team
ext_teams = extras_by_team['bowling_team'].tolist()
ext_total = extras_by_team['total_extras'].tolist()
ext_wides = extras_by_team['wides'].tolist()
ext_noballs = extras_by_team['noballs'].tolist()

# Venue RPO
v_names = venue_stats['venue_short'].tolist()
v_rpo = venue_stats['avg_rpo'].tolist()
v_wickets = venue_stats['avg_wickets_per_match'].tolist()

print("\n=== Data extraction complete ===")

# ── Generate HTML ──────────────────────────────────────────────────────────────

def js_arr(lst):
    return json.dumps(lst)

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>IPL 2026 Ball-by-Ball Analytics Report</title>
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
  <style>
    :root {{
      --primary: #1a2a4a;
      --accent: #e85d04;
      --accent2: #f48c06;
      --gold: #ffd60a;
      --bg: #0d1b2a;
      --card: #162032;
      --card2: #1e2d42;
      --text: #e8edf3;
      --text2: #94a3b8;
      --green: #22c55e;
      --red: #ef4444;
      --border: #2a3f5f;
    }}
    * {{ box-sizing: border-box; margin: 0; padding: 0; }}
    body {{
      background: var(--bg);
      color: var(--text);
      font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
      font-size: 14px;
      line-height: 1.6;
    }}
    /* ── Header ── */
    .header {{
      background: linear-gradient(135deg, #0d1b2a 0%, #1a3a5c 50%, #0d1b2a 100%);
      border-bottom: 3px solid var(--accent);
      padding: 40px 48px 32px;
      position: relative;
      overflow: hidden;
    }}
    .header::before {{
      content: '';
      position: absolute; inset: 0;
      background: radial-gradient(ellipse at 70% 50%, rgba(232,93,4,0.12) 0%, transparent 60%);
    }}
    .header-inner {{ position: relative; max-width: 1400px; margin: 0 auto; }}
    .badge {{
      display: inline-block;
      background: var(--accent);
      color: #fff;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      padding: 4px 12px;
      border-radius: 2px;
      margin-bottom: 12px;
    }}
    h1 {{
      font-size: 2.6rem;
      font-weight: 800;
      letter-spacing: -0.5px;
      color: #fff;
      line-height: 1.15;
    }}
    h1 span {{ color: var(--accent); }}
    .subtitle {{
      margin-top: 8px;
      color: var(--text2);
      font-size: 1.05rem;
    }}
    .meta {{
      margin-top: 18px;
      display: flex;
      gap: 28px;
      flex-wrap: wrap;
    }}
    .meta-item {{
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
      color: var(--text2);
    }}
    .meta-item strong {{ color: var(--text); }}
    /* ── Layout ── */
    .container {{ max-width: 1400px; margin: 0 auto; padding: 32px 48px; }}
    /* ── Section headings ── */
    .section-header {{
      display: flex;
      align-items: center;
      gap: 12px;
      margin: 48px 0 20px;
