innings_stats['rpo'] = (innings_stats['total_runs'] / (innings_stats['balls']/6)).round(2)
innings_stats['boundary_pct'] = (innings_stats['boundaries'] / innings_stats['balls'] * 100).round(1)
innings_stats['dot_pct'] = (innings_stats['dots'] / innings_stats['balls'] * 100).round(1)

print("\n=== Innings Stats ===")
print(innings_stats.to_string(index=False))

