      grid-column: 1 / -1;
    }}
    .chart-title {{
      font-size: 13px;
      font-weight: 600;
      color: var(--text2);
      text-transform: uppercase;
      letter-spacing: 0.7px;
      margin-bottom: 16px;
    }}
    .chart-container {{ position: relative; }}
    /* ── Tables ── */
    .table-wrap {{ overflow-x: auto; }}
    table {{
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
    }}
    thead th {{
      background: var(--card2);
      color: var(--text2);
      font-weight: 600;
      font-size: 11px;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      padding: 10px 14px;
      text-align: left;
