    tbody td.right {{ text-align: right; }}
    tbody td.accent {{ color: var(--accent2); font-weight: 700; }}
    tbody td.green {{ color: var(--green); }}
    tbody td.red {{ color: var(--red); }}
    .rank-badge {{
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 22px; height: 22px;
      background: var(--accent);
      color: #fff;
      border-radius: 50%;
      font-size: 11px;
      font-weight: 700;
      margin-right: 8px;
