    .phase-name {{
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.7px;
      color: var(--text2);
      margin-bottom: 14px;
    }}
    .phase-stat {{
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 6px 0;
      border-bottom: 1px solid var(--border);
      font-size: 13px;
    }}
    .phase-stat:last-child {{ border-bottom: none; }}
    .phase-stat-val {{
      font-weight: 700;
      color: var(--accent2);
    }}
    /* ── Insights box ── */
    .insight-box {{
      background: linear-gradient(135deg, rgba(232,93,4,0.1), rgba(244,140,6,0.05));
