    }}
    .insight-box h4 {{
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.7px;
      color: var(--accent2);
      margin-bottom: 8px;
    }}
    .insight-box ul {{
      list-style: none;
      padding: 0;
    }}
    .insight-box ul li {{
      padding: 3px 0;
      font-size: 13px;
      color: var(--text);
    }}
    .insight-box ul li::before {{
      content: '▸ ';
      color: var(--accent);
    }}
    /* ── Footer ── */
    .footer {{
      background: var(--card);
      border-top: 1px solid var(--border);
      padding: 24px 48px;
      text-align: center;
      color: var(--text2);
      font-size: 12px;
      margin-top: 48px;
    }}
    .toc {{
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 24px 28px;
      margin-bottom: 36px;
    }}
    .toc h3 {{
      font-size: 14px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--text2);
      margin-bottom: 14px;
    }}
    .toc ol {{
      list-style: none;
      padding: 0;
      columns: 2;
      column-gap: 32px;
    }}
    .toc ol li {{
      padding: 4px 0;
      font-size: 13px;
    }}
    .toc ol li a {{
      color: var(--text);
      text-decoration: none;
      transition: color 0.15s;
    }}
    .toc ol li a:hover {{ color: var(--accent2); }}
    .toc-num {{ color: var(--accent); font-weight: 700; margin-right: 6px; }}
  </style>
</head>
