    <h2>Batting Performance Analysis</h2>
  </div>
  <div class="divider"></div>

  <!-- Phase summary cards -->
  <div class="phase-grid">"""

# Insert phase cards dynamically
for _, row in phase_bat.iterrows():
    html += f"""
    <div class="phase-card">
      <div class="phase-name">{row['phase']}</div>
      <div class="phase-stat"><span>Run Rate</span><span class="phase-stat-val">{row['run_rate']}</span></div>
      <div class="phase-stat"><span>Boundary %</span><span class="phase-stat-val">{row['boundary_pct']}%</span></div>
      <div class="phase-stat"><span>Dot Ball %</span><span class="phase-stat-val">{row['dot_pct']}%</span></div>
