      <div class="phase-stat"><span>Total Runs</span><span class="phase-stat-val">{int(row['total_runs'])}</span></div>
    </div>"""

html += f"""
  </div>

  <div class="charts-2col">
    <div class="chart-card">
      <div class="chart-title">Top 10 Run Scorers — Runs &amp; Strike Rate</div>
      <div class="chart-container" style="height:320px">
