        <canvas id="boundaryChart"></canvas>
      </div>
    </div>
  </div>

  <div class="charts-2col">
    <div class="chart-card">
      <div class="chart-title">Over-by-Over Run Rate (all matches)</div>
      <div class="chart-container" style="height:280px">
        <canvas id="overRPOChart"></canvas>
      </div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Phase-wise Scoring Comparison</div>
      <div class="chart-container" style="height:280px">
        <canvas id="phaseChart"></canvas>
      </div>
    </div>
  </div>

  <!-- Top batters table -->
  <div class="chart-card" style="margin-bottom:20px">
    <div class="chart-title">Top 15 Run Scorers — Detailed Statistics</div>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Rank</th>
            <th>Batter</th>
            <th class="right">Runs</th>
            <th class="right">Balls</th>
            <th class="right">Strike Rate</th>
            <th class="right">4s</th>
            <th class="right">6s</th>
            <th class="right">Boundary %</th>
          </tr>
        </thead>
        <tbody>"""

for i, (_, row) in enumerate(bat_agg.iterrows()):
    rank_class = "" if i > 2 else ["", "silver", "bronze"][i] if i > 0 else ""
    rank_html = f'<span class="rank-badge{" " + rank_class if rank_class else ""}">{i+1}</span>'
    b_pct = round(100 * (row['fours'] + row['sixes']) / row['balls'], 1) if row['balls'] > 0 else 0
    html += f"""
          <tr>
            <td>{rank_html}</td>
            <td><strong>{row['striker']}</strong></td>
            <td class="right accent">{int(row['runs'])}</td>
            <td class="right">{int(row['balls'])}</td>
            <td class="right">{"<span class='green'>" if row['strike_rate'] >= 150 else ""}{row['strike_rate']}{"</span>" if row['strike_rate'] >= 150 else ""}</td>
            <td class="right">{int(row['fours'])}</td>
            <td class="right">{int(row['sixes'])}</td>
            <td class="right">{b_pct}%</td>
          </tr>"""

html += f"""
        </tbody>
      </table>
    </div>
  </div>

  <div class="insight-box">
    <h4>Batting Insights</h4>
    <ul>
      <li>Death overs ({phase_bat[phase_bat['phase']=='Death (15-19)']['run_rate'].values[0]} RPO) significantly outpace the powerplay ({phase_bat[phase_bat['phase']=='Powerplay (0-5)']['run_rate'].values[0]} RPO) and middle overs ({phase_bat[phase_bat['phase']=='Middle (6-14)']['run_rate'].values[0]} RPO) in scoring rate.</li>
      <li>Powerplay dot ball rate: <strong>{phase_bat[phase_bat['phase']=='Powerplay (0-5)']['dot_pct'].values[0]}%</strong> — batters show early caution despite field restrictions.</li>
      <li>Middle overs contribute the highest wicket count ({int(phase_bat[phase_bat['phase']=='Middle (6-14)']['wickets'].values[0])} wickets), indicating spinners dominate in overs 7-14.</li>
    </ul>
  </div>
</div>

<!-- ════════════════════════  SECTION 4: BOWLING  ════════════════════════ -->
<div id="bowling">
