for i, (_, row) in enumerate(bowl_agg_wickets.iterrows()):
    eco_class = "green" if row['economy'] < 8.5 else ("red" if row['economy'] > 10.5 else "")
    html += f"""
          <tr>
            <td><span class="rank-badge{'' if i>0 else ''}">{i+1}</span></td>
            <td><strong>{row['bowler']}</strong></td>
            <td class="right accent">{int(row['wickets'])}</td>
