for _, row in dismissals.iterrows():
    pct = round(100 * row['count'] / total_wickets, 1)
    html += f"""
          <tr>
            <td><strong>{row['wicket_type'].title()}</strong></td>
            <td class="right accent">{int(row['count'])}</td>
            <td class="right">{pct}%</td>
          </tr>"""

html += f"""
        </tbody>
      </table>
    </div>
  </div>

  <div class="insight-box">
    <h4>Bowling Insights</h4>
    <ul>
      <li>Caught dismissals dominate at <strong>{dismissals[dismissals['wicket_type']=='caught']['count'].values[0] if 'caught' in dismissals['wicket_type'].values else 'N/A'}</strong> instances — outfielders and slip cordon are key.</li>
      <li>A high dot ball % correlates strongly with wicket-taking: top dot-ball bowlers create sustained pressure.</li>
      <li>Tournament economy average: <strong>{bowl_agg['economy'].mean():.2f} RPO</strong> — above T20 norms, indicating a bat-dominant season so far.</li>
    </ul>
  </div>
</div>

<!-- ════════════════════════  SECTION 5: TEAMS  ════════════════════════ -->
